Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();

    if (user?.role !== 'admin') {
      return Response.json({ error: 'Admin access required' }, { status: 403 });
    }

    // Delete existing cards
    const existing = await base44.asServiceRole.entities.TarotCard.list("-updated_date", 100);
    for (const card of existing) {
      await base44.asServiceRole.entities.TarotCard.delete(card.id);
    }

    // Create all 78 cards
    await base44.asServiceRole.entities.TarotCard.bulkCreate(TAROT_CARDS);

    return Response.json({ success: true, message: `Seeded ${TAROT_CARDS.length} tarot cards` });
  } catch (error) {
    console.error('Seed error:', error);
    return Response.json({ error: error.message }, { status: 500 });
  }
});